"""Synthetic evaluation dataset generation: real questions generated by an LLM from a
document's real persisted chunks, with ground-truth answers and real source chunk IDs — never
hand-written fixtures pretending to be a generated set. Covers factoid, multi-hop (via real
graph-linked chunk pairs), comparison, and unanswerable categories; PII questions reuse chunks
the pipeline already flagged as containing PII tokens rather than being a fifth generation path.
"""

from __future__ import annotations

import json
import uuid
from datetime import UTC, datetime
from pathlib import Path

import numpy as np
from pydantic import BaseModel
from sqlalchemy import select

from app.chunking.models import ChunkRow
from app.core.config import get_settings
from app.core.db import session_scope
from app.embeddings.registry import get_embedder
from app.evaluation.models import EvalDataset
from app.llm.client import LlmUnavailableError, complete
from app.llm.json_utils import extract_json_object
from app.stores.graph.networkx_store import get_graph_store

DEDUPE_SIMILARITY_THRESHOLD = 0.95


class EvalItem(BaseModel):
    id: str
    category: str  # factoid | multi_hop | comparison | unanswerable | pii
    question: str
    ground_truth_answer: str
    source_chunk_ids: list[str]


_FACTOID_PROMPT = (
    "Given this excerpt, write one factual question that is directly and unambiguously "
    "answered by it, plus the answer. Return ONLY a JSON object: "
    '{{"question": "...", "answer": "..."}}\n\nExcerpt:\n{text}'
)

_MULTI_HOP_PROMPT = (
    "Given these two related excerpts, write one question that requires information from "
    "BOTH to answer, plus the combined answer. Return ONLY a JSON object: "
    '{{"question": "...", "answer": "..."}}\n\nExcerpt 1:\n{text_a}\n\nExcerpt 2:\n{text_b}'
)

_COMPARISON_PROMPT = (
    "Given these two excerpts, write one question that asks the reader to compare or "
    "contrast something between them, plus the answer. Return ONLY a JSON object: "
    '{{"question": "...", "answer": "..."}}\n\nExcerpt 1:\n{text_a}\n\nExcerpt 2:\n{text_b}'
)

_UNANSWERABLE_PROMPT = (
    "Given this excerpt, write one question that sounds plausible for this kind of document "
    "but is NOT actually answered by this specific excerpt (ask about a related fact it does "
    "not contain). Return ONLY a JSON object: "
    '{{"question": "...", "answer": "Not answerable from this document."}}\n\nExcerpt:\n{text}'
)

_PII_PROMPT = (
    "This excerpt contains a masked PII placeholder token like <TYPE_hex>. Write one question "
    "that asks about that piece of contact/personal information, plus an answer that just "
    "names which token answers it. Return ONLY a JSON object: "
    '{{"question": "...", "answer": "..."}}\n\nExcerpt:\n{text}'
)


async def _generate_one(prompt: str) -> dict | None:
    try:
        raw = await complete(prompt, max_tokens=300, temperature=0.4)
    except LlmUnavailableError:
        return None
    parsed = extract_json_object(raw)
    if not parsed or "question" not in parsed or "answer" not in parsed:
        return None
    return parsed


async def _dedupe(items: list[EvalItem]) -> list[EvalItem]:
    if len(items) < 2:
        return items
    embedder = get_embedder()
    embeddings = embedder.embed([item.question for item in items])
    kept: list[EvalItem] = []
    kept_embeddings: list[np.ndarray] = []
    for item, emb in zip(items, embeddings, strict=True):
        is_dup = any(
            float((emb * other).sum()) >= DEDUPE_SIMILARITY_THRESHOLD for other in kept_embeddings
        )
        if not is_dup:
            kept.append(item)
            kept_embeddings.append(emb)
    return kept


async def generate_dataset(document_id: str, target_size: int = 20) -> list[EvalItem]:
    async with session_scope() as session:
        rows = (
            (
                await session.execute(
                    select(ChunkRow).where(
                        ChunkRow.doc_id == document_id, ChunkRow.variant == "default"
                    )
                )
            )
            .scalars()
            .all()
        )
    if not rows:
        return []

    chunks = list(rows)
    items: list[EvalItem] = []
    per_category = max(target_size // 5, 1)

    for chunk in chunks[:per_category]:
        parsed = await _generate_one(_FACTOID_PROMPT.format(text=chunk.text[:1500]))
        if parsed:
            items.append(
                EvalItem(
                    id=str(uuid.uuid4()),
                    category="factoid",
                    question=parsed["question"],
                    ground_truth_answer=parsed["answer"],
                    source_chunk_ids=[chunk.chunk_id],
                )
            )

    graph_data = get_graph_store().to_json(doc_id=document_id)
    chunk_by_id = {c.chunk_id: c for c in chunks}
    linked_pairs = [
        (e["chunk_id"], other["chunk_id"])
        for e in graph_data["edges"]
        if e.get("chunk_id")
        for other in graph_data["edges"]
        if other.get("chunk_id") and other["chunk_id"] != e["chunk_id"]
    ][:per_category]
    for chunk_id_a, chunk_id_b in linked_pairs:
        if chunk_id_a not in chunk_by_id or chunk_id_b not in chunk_by_id:
            continue
        parsed = await _generate_one(
            _MULTI_HOP_PROMPT.format(
                text_a=chunk_by_id[chunk_id_a].text[:1000],
                text_b=chunk_by_id[chunk_id_b].text[:1000],
            )
        )
        if parsed:
            items.append(
                EvalItem(
                    id=str(uuid.uuid4()),
                    category="multi_hop",
                    question=parsed["question"],
                    ground_truth_answer=parsed["answer"],
                    source_chunk_ids=[chunk_id_a, chunk_id_b],
                )
            )

    for i in range(0, min(len(chunks) - 1, per_category * 2), 2):
        a, b = chunks[i], chunks[i + 1]
        parsed = await _generate_one(
            _COMPARISON_PROMPT.format(text_a=a.text[:1000], text_b=b.text[:1000])
        )
        if parsed:
            items.append(
                EvalItem(
                    id=str(uuid.uuid4()),
                    category="comparison",
                    question=parsed["question"],
                    ground_truth_answer=parsed["answer"],
                    source_chunk_ids=[a.chunk_id, b.chunk_id],
                )
            )

    for chunk in chunks[:per_category]:
        parsed = await _generate_one(_UNANSWERABLE_PROMPT.format(text=chunk.text[:1500]))
        if parsed:
            items.append(
                EvalItem(
                    id=str(uuid.uuid4()),
                    category="unanswerable",
                    question=parsed["question"],
                    ground_truth_answer="Not answerable from this document.",
                    source_chunk_ids=[chunk.chunk_id],
                )
            )

    pii_chunks = [c for c in chunks if c.pii_token_count > 0][:per_category]
    for chunk in pii_chunks:
        parsed = await _generate_one(_PII_PROMPT.format(text=chunk.text[:1500]))
        if parsed:
            items.append(
                EvalItem(
                    id=str(uuid.uuid4()),
                    category="pii",
                    question=parsed["question"],
                    ground_truth_answer=parsed["answer"],
                    source_chunk_ids=[chunk.chunk_id],
                )
            )

    return await _dedupe(items)


def _dataset_dir(document_id: str) -> Path:
    path = get_settings().data_dir / "eval_datasets" / document_id
    path.mkdir(parents=True, exist_ok=True)
    return path


async def save_dataset(document_id: str, items: list[EvalItem]) -> EvalDataset:
    async with session_scope() as session:
        existing_count = (
            (
                await session.execute(
                    select(EvalDataset).where(EvalDataset.document_id == document_id)
                )
            )
            .scalars()
            .all()
        )
    version = len(existing_count) + 1

    path = _dataset_dir(document_id) / f"v{version}.jsonl"
    with path.open("w", encoding="utf-8") as fh:
        for item in items:
            fh.write(item.model_dump_json() + "\n")

    dataset_id = str(uuid.uuid4())
    async with session_scope() as session:
        record = EvalDataset(
            id=dataset_id,
            document_id=document_id,
            version=version,
            path=str(path),
            item_count=len(items),
            created_at=datetime.now(UTC),
        )
        session.add(record)
        await session.commit()
    return record


def load_dataset(path: str) -> list[EvalItem]:
    items = []
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            if line.strip():
                items.append(EvalItem(**json.loads(line)))
    return items
